//! Actions-only current typed directory READ -> snapshot/partial roster, with
//! Group.Update/system-control races and explicit recovery. No raw API grants.
use super::*;
use n::{relation_roster::{self,RosterRead,NativeRelationRosterConfig},relation_journal::RelationConfiguration,rpc_im::{ImQuery,OwnedImReply},group_directory_data::Relation};
fn fixture()->Fixture{let mut f=Fixture::with_directory(true,false,true);f.temp.database.with_conn(|c|relation_roster::initialize_schema(c)).unwrap();f.backend.close();let mut b=OfflineBackend::new(f.owner.clone());b.claim_common_transport().unwrap();b.bind_common_identity(b"AccountEntry").unwrap();let cfg=NativeReceiverConfig{direct_domains:None,invite_notifications:None,im_messages:Some(NativeImConfig{notification_timeout_ms:30000,receive_info:false,directory_queries:true})};let p=NativeReceiverPolicy::capture(&cfg).unwrap().with_relation_roster(NativeRelationRosterConfig{observe:true}).unwrap();b.arm_native_receivers(NativeReceiverSetup::capture(p,true,None).unwrap()).unwrap();f.scope=b.connection_scope();let p=b.prepare_login(login(),&[]).unwrap();b.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,&login_result()),0).unwrap();b.configure_native_receivers(7).unwrap();f.backend=b;f}
fn relation(label:&[u8],flags:u32)->Relation<'_>{Relation{label,flags,first:b"private-note",second:b"",properties:vec![]}}
fn body(accepted:bool,partial:bool,time:i64,adds:&[(&[u8],u32)],updates:&[(&[u8],u32)],removed:&[&[u8]])->Vec<u8>{let mut w=Writer::new();w.boolean(accepted).unwrap();w.boolean(partial).unwrap();for items in [adds,updates]{w.u32(items.len()as u32).unwrap();for(label,flags)in items{w.bytes(label).unwrap();w.u32(*flags).unwrap();w.bytes(b"private-note").unwrap();w.bytes(b"").unwrap();w.properties(&[]).unwrap();}}w.u32(removed.len()as u32).unwrap();for label in removed{w.bytes(label).unwrap();}w.i64(time).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn query(group:Option<&[u8]>,since:i64)->Arc<ImQuery>{Arc::new(ImQuery::relations(group.map(n::group_directory_data::GroupId::parse).transpose().unwrap(),since).unwrap())}
fn prepare(f:&Fixture,q:Arc<ImQuery>)->RosterRead{let b=f.backend.captured_im_binding().unwrap();let config=Arc::new(f.temp.database.with_conn(|c|RelationConfiguration::capture(c,f.run.line_id(),f.run.revision(),Some(&f.scope))).unwrap());f.temp.database.with_conn(|c|RosterRead::capture(f.temp.database.clone(),c,f.run.clone(),b,f.gate.clone(),config,q)).unwrap()}
fn reply(f:&mut Fixture,q:Arc<ImQuery>,bytes:&[u8])->OwnedImReply{let p=f.backend.prepare_im_read(q,f.gate.clone(),Instant::now()+Duration::from_secs(3)).unwrap();f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,bytes),0).unwrap();f.backend.take_im_replies().pop().unwrap()}
fn snapshot(f:&mut Fixture,group:Option<&[u8]>,time:i64,items:&[(&[u8],u32)]){let q=query(group,-1);let read=prepare(f,q.clone());let r=reply(f,q,&body(true,false,time,items,&[],&[]));let v=read.commit(&f.temp.database,&r).unwrap();assert_eq!(v.outcome,"snapshot");assert!(v.complete_roster);}
fn observe(f:&Fixture,group:Option<&[u8]>,base:Option<i64>,time:Option<i64>,items:&[(&[u8],u32)]){let b=f.backend.captured_im_binding().unwrap();let items=items.iter().map(|(id,flags)|relation(id,*flags)).collect::<Vec<_>>();f.temp.database.with_conn(|c|{let tx=rusqlite::Transaction::new_unchecked(c,rusqlite::TransactionBehavior::Immediate).map_err(|_|"fixture")?;relation_roster::observe(&tx,&f.run,&b,group,base,time,&items)?;tx.commit().map_err(|_|"fixture")}).unwrap();}
fn view(f:&Fixture)->Vec<relation_roster::RosterView>{f.temp.database.with_conn(|c|relation_roster::history(c,f.run.line_id(),128)).unwrap()}
#[test]fn roster_original_complete_result_is_first_map_relationlist_not_partial_flag_or_extra_maps(){let mut f=fixture();let q=query(None,-1);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,false,7,&[(b"one",1)],&[(b"ignored-update",1)],&[b"ignored-removal"]));let v=read.commit(&f.temp.database,&r).unwrap();assert_eq!(v.outcome,"snapshot");assert_eq!(v.members,1);assert!(v.complete_roster);assert!(view(&f)[0].historical_complete);assert_eq!(f.count(),0);assert!(f.temp.database.with_conn(|c|n::relation_journal::history(c,f.run.line_id(),128)).unwrap().is_empty());}
#[test]fn roster_partial_without_matching_original_baseline_cannot_be_complete(){let mut f=fixture();let q=query(None,0);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,true,1,&[(b"one",1)],&[],&[]));let v=read.commit(&f.temp.database,&r).unwrap();assert_eq!(v.outcome,"baseline_required");assert!(!v.complete_roster);assert!(view(&f).is_empty());}
#[test]fn roster_current_partial_read_applies_added_updated_removed_to_exact_since(){let mut f=fixture();snapshot(&mut f,Some(b"1-2"),7,&[(b"one",1),(b"two",1)]);let q=query(Some(b"1-2"),7);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,true,9,&[(b"three",1)],&[(b"one",2)],&[b"two"]));let v=read.commit(&f.temp.database,&r).unwrap();assert_eq!(v.outcome,"incremental");assert_eq!(v.members,2);let row=&view(&f)[0];assert_eq!(row.baseline_time.as_deref(),Some("7"));assert_eq!(row.observed_time.as_deref(),Some("9"));assert!(row.historical_complete&&!row.gap);}
#[test]fn roster_event_before_any_snapshot_never_populates_or_promotes_complete_roster(){let f=fixture();observe(&f,Some(b"1-2"),Some(0),Some(1),&[(b"one",1)]);let row=&view(&f)[0];assert!(!row.historical_complete);assert!(row.gap);assert_eq!(row.members,0);assert_eq!(row.observed_time,None);assert_eq!(row.target_time.as_deref(),Some("1"));}
#[test]fn roster_contiguous_event_changes_members_but_missing_span_freezes_observed_until_explicit_read(){let mut f=fixture();snapshot(&mut f,None,1,&[(b"one",1)]);observe(&f,None,Some(1),Some(2),&[(b"one",20),(b"two",1)]);assert_eq!(view(&f)[0].members,1);assert_eq!(view(&f)[0].observed_time.as_deref(),Some("2"));observe(&f,None,Some(4),Some(5),&[(b"three",1)]);let row=&view(&f)[0];assert_eq!(row.observed_time.as_deref(),Some("2"));assert_eq!(row.target_time.as_deref(),Some("5"));assert!(row.gap&&!row.historical_complete);let q=query(None,2);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,true,5,&[(b"three",1)],&[],&[]));assert!(read.commit(&f.temp.database,&r).unwrap().complete_roster);assert_eq!(view(&f)[0].members,2);assert!(!view(&f)[0].gap);}
#[test]fn roster_late_snapshot_cannot_overwrite_event_admitted_after_its_serial_capture(){let mut f=fixture();snapshot(&mut f,None,1,&[(b"one",1)]);let q=query(None,-1);let read=prepare(&f,q.clone());observe(&f,None,Some(1),Some(2),&[(b"two",1)]);let r=reply(&mut f,q,&body(true,false,99,&[(b"wrong",1)],&[],&[]));let v=read.commit(&f.temp.database,&r).unwrap();assert_eq!(v.outcome,"superseded");assert!(!v.complete_roster);assert_eq!(view(&f)[0].members,2);assert_eq!(view(&f)[0].observed_time.as_deref(),Some("2"));}
#[test]fn roster_newer_target_blocks_stale_full_result_even_with_matching_serial(){let mut f=fixture();observe(&f,None,Some(9),Some(10),&[(b"one",1)]);let q=query(None,-1);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,false,9,&[(b"old",1)],&[],&[]));assert_eq!(read.commit(&f.temp.database,&r).unwrap().outcome,"stale");assert!(!view(&f)[0].historical_complete);assert_eq!(view(&f)[0].members,0);snapshot(&mut f,None,10,&[(b"current",1)]);assert!(view(&f)[0].historical_complete);}
#[test]fn roster_equal_time_or_missing_time_event_requires_full_snapshot_not_empty_partial_clearance(){for missing in [false,true]{let mut f=fixture();snapshot(&mut f,None,1,&[(b"one",1)]);observe(&f,None,if missing{None}else{Some(0)},if missing{None}else{Some(1)},&[(b"changed",1)]);let q=query(None,1);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,true,2,&[],&[],&[]));assert_eq!(read.commit(&f.temp.database,&r).unwrap().outcome,"baseline_required");assert!(view(&f)[0].gap);snapshot(&mut f,None,2,&[(b"actual",1)]);assert!(view(&f)[0].historical_complete);}}
#[test]fn roster_failed_event_transaction_rolls_back_full_replacement_not_only_public_event(){let mut f=fixture();snapshot(&mut f,None,1,&[(b"one",1)]);f.temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER fail_roster BEFORE INSERT ON app_events WHEN NEW.event_type='app_voice.relation_roster_observed' BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();let q=query(None,-1);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,false,2,&[(b"two",1),(b"three",1)],&[],&[]));assert!(read.commit(&f.temp.database,&r).is_err());let row=&view(&f)[0];assert_eq!(row.members,1);assert_eq!(row.observed_time.as_deref(),Some("1"));}
#[test]fn roster_foreign_query_gate_config_and_database_cannot_replace_current_state(){for mode in 0..4{let mut f=fixture();let q=query(None,-1);let read=prepare(&f,q.clone());let request=if mode==0{query(None,-1)}else{q};let r=reply(&mut f,request,&body(true,false,1,&[(b"one",1)],&[],&[]));let other=fixture();match mode{1=>f.gate.retire(),2=>{f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_accounts SET private_config=X'00'",[]).map_err(|_|"fixture")).unwrap();},_=>{}}assert!(read.commit(if mode==3{&other.temp.database}else{&f.temp.database},&r).is_err());assert!(view(&f).is_empty());}}
#[test]fn roster_history_and_debug_never_export_raw_target_member_property_uid_or_permission(){let mut f=fixture();snapshot(&mut f,Some(b"711111111-822222222"),i64::MAX,&[(b"private-label",1)]);let row=view(&f);assert_eq!(row[0].observed_time.as_deref(),Some("9223372036854775807"));let s=serde_json::to_string(&row).unwrap();for private in ["711111111-822222222","private-label","private-note","fixture-user","token","identity_key","receipt_epoch"]{assert!(!s.contains(private));}assert!(relation_roster::NativeRelationRosterConfig{observe:false}.validate().is_err());}

fn expanded_ignored_map()->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.boolean(false).unwrap();w.u32(0).unwrap();w.u32(40).unwrap();for i in 0..40u8{w.bytes(&[i]).unwrap();w.u32(1).unwrap();w.bytes(b"").unwrap();w.bytes(b"").unwrap();w.u32(128).unwrap();for key in 0..128u8{w.bytes(&[key]).unwrap();w.bytes(b"").unwrap();}}w.u32(0).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
#[test]fn roster_directory_ignored_second_map_expansion_is_charged_before_decode_not_only_wire_bytes(){
 let bytes=expanded_ignored_map();assert!(bytes.len()<65536);assert!(n::group_directory_data::relations_decode_size(0,&bytes).unwrap()>n::rpc_stream::MAX_STREAM_BYTES);
 let mut f=fixture();let q=query(None,-1);let read=prepare(&f,q.clone());let before=f.scope.native_rpc_resources();let p=f.backend.prepare_im_read(q,f.gate.clone(),Instant::now()+Duration::from_secs(3)).unwrap();
 assert!(f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,&bytes),0).is_err());assert!(f.backend.take_im_replies().is_empty());assert!(!f.scope.is_open());assert_eq!(f.scope.native_rpc_resources(),before);assert!(view(&f).is_empty());drop(read);assert_eq!(f.scope.native_rpc_resources(),(0,0));
}
#[test]fn roster_directory_decoded_vectors_keep_original_shared_budget_until_actual_drop_after_close(){
 let mut f=fixture();let bytes=body(true,false,1,&[(b"one",1)],&[(b"ignored",1)],&[b"ignored-name"]);let r=reply(&mut f,query(None,-1),&bytes);let baseline=f.scope.native_rpc_resources();let size=n::group_directory_data::relations_decode_size(0,&bytes).unwrap();
 assert_eq!(size,128+2*std::mem::size_of::<Relation<'_>>()+std::mem::size_of::<&[u8]>());
 let first=r.result().unwrap();assert_eq!(f.scope.native_rpc_resources(),(baseline.0+1,baseline.1+size));let second=r.result().unwrap();assert_eq!(f.scope.native_rpc_resources(),(baseline.0+2,baseline.1+2*size));
 f.scope.close();assert_eq!(f.scope.native_rpc_resources(),(baseline.0+2,baseline.1+2*size));drop(first);assert_eq!(f.scope.native_rpc_resources(),(baseline.0+1,baseline.1+size));drop(second);assert_eq!(f.scope.native_rpc_resources(),baseline);drop(r);assert_eq!(f.scope.native_rpc_resources(),(0,0));
}
#[test]fn roster_directory_scratch_uses_original_remaining_bytes_and_cannot_decode_at_full_budget(){
 let mut f=fixture();let bytes=body(true,false,1,&[(b"one",1)],&[],&[]);let r=reply(&mut f,query(None,-1),&bytes);let before=f.scope.native_rpc_resources();let full=f.scope.reserve_native_rpc(n::rpc_stream::MAX_STREAM_BYTES-before.1).unwrap();assert!(r.result().is_err());assert_eq!(f.scope.native_rpc_resources(),(before.0+1,n::rpc_stream::MAX_STREAM_BYTES));assert!(f.scope.is_open());drop(full);assert!(r.result().is_ok());assert_eq!(f.scope.native_rpc_resources(),before);drop(r);assert_eq!(f.scope.native_rpc_resources(),(0,0));
}
#[test]fn roster_directory_properties_and_footer_headers_are_precharged_and_duplicate_failure_releases_scratch(){
 let f=fixture();let mut w=Writer::new();w.boolean(true).unwrap();w.properties(&[RpcProperty{key:b"a",value:b"b"}]).unwrap();w.bytes(b"").unwrap();w.properties(&[RpcProperty{key:b"c",value:b"d"}]).unwrap();let bytes=w.finish();let bytes=bytes.expose_to_transport();let size=n::group_directory_data::properties_decode_size(0,bytes).unwrap();assert_eq!(size,128+2*std::mem::size_of::<RpcProperty<'_>>());let v=n::group_directory_data::decode_properties_scoped(&f.scope,0,bytes).unwrap();assert_eq!(f.scope.native_rpc_resources(),(1,size));assert_eq!(v.footer.properties.len(),1);drop(v);assert_eq!(f.scope.native_rpc_resources(),(0,0));
 let mut w=Writer::new();w.boolean(true).unwrap();w.u32(2).unwrap();for _ in 0..2{w.bytes(b"same").unwrap();w.bytes(b"").unwrap();}w.bytes(b"").unwrap();let bytes=w.finish();assert!(n::group_directory_data::properties_decode_size(0,bytes.expose_to_transport()).is_ok());assert!(n::group_directory_data::decode_properties_scoped(&f.scope,0,bytes.expose_to_transport()).is_err());assert_eq!(f.scope.native_rpc_resources(),(0,0));
 let mut w=Writer::new();w.boolean(true).unwrap();w.boolean(false).unwrap();for _ in 0..2{w.u32(1).unwrap();w.bytes(b"label").unwrap();w.u32(1).unwrap();w.bytes(b"").unwrap();w.bytes(b"").unwrap();w.properties(&[RpcProperty{key:b"p",value:b"v"}]).unwrap();}w.u32(1).unwrap();w.bytes(b"name").unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.properties(&[RpcProperty{key:b"footer",value:b"v"}]).unwrap();let wire=w.finish();let wire=wire.expose_to_transport();let size=n::group_directory_data::relations_decode_size(0,wire).unwrap();assert_eq!(size,128+2*std::mem::size_of::<Relation<'_>>()+3*std::mem::size_of::<RpcProperty<'_>>()+std::mem::size_of::<&[u8]>());let v=n::group_directory_data::decode_relations_scoped(&f.scope,0,wire).unwrap();assert_eq!(f.scope.native_rpc_resources(),(1,size));drop(v);assert_eq!(f.scope.native_rpc_resources(),(0,0));
}
#[test]fn roster_byte_capacity_replacement_releases_larger_old_values_before_any_growth(){
 let mut f=fixture();snapshot(&mut f,None,1,&[(b"small",1),(b"shrink",1)]);let baseline:i64=f.temp.database.with_conn(|c|c.query_row("SELECT SUM(length(relation)) FROM app_voice_relation_roster_members",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();
 // Fill the private SQL body budget without native decode allocations. The
 // touched label keys remain those produced by a real snapshot. Untouched
 // synthetic rows model other stored history, never current READ authority.
 f.temp.database.with_conn(|c|{let tx=rusqlite::Transaction::new_unchecked(c,rusqlite::TransactionBehavior::Immediate).map_err(|_|"fixture")?;let old:i64=tx.query_row("SELECT length(relation) FROM app_voice_relation_roster_members WHERE instr(relation,?1)>0",[b"shrink".as_slice()],|r|r.get(0)).map_err(|_|"fixture")?;tx.execute("UPDATE app_voice_relation_roster_members SET relation=zeroblob(60000) WHERE instr(relation,?1)>0",[b"shrink".as_slice()]).map_err(|_|"fixture")?;let id:i64=tx.query_row("SELECT id FROM app_voice_relation_rosters",[],|r|r.get(0)).map_err(|_|"fixture")?;let mut remaining=16*1024*1024-(baseline-old+60000);let mut i=0u32;while remaining>0{let n=remaining.min(65536);let mut key=[0u8;32];key[..4].copy_from_slice(&i.to_be_bytes());tx.execute("INSERT INTO app_voice_relation_roster_members(roster_id,label_key,relation) VALUES(?1,?2,zeroblob(?3))",rusqlite::params![id,key.as_slice(),n]).map_err(|_|"fixture")?;remaining-=n;i+=1;}tx.commit().map_err(|_|"fixture")}).unwrap();
 let q=query(None,1);let read=prepare(&f,q.clone());let mut w=Writer::new();w.boolean(true).unwrap();w.boolean(true).unwrap();w.u32(0).unwrap();w.u32(2).unwrap();for(label,len)in[(b"small".as_slice(),10000),(b"shrink".as_slice(),0)]{w.bytes(label).unwrap();w.u32(1).unwrap();w.bytes(&vec![b'x';len]).unwrap();w.bytes(b"").unwrap();w.properties(&[]).unwrap();}w.u32(0).unwrap();w.i64(2).unwrap();w.bytes(b"").unwrap();let r=reply(&mut f,q,w.finish().expose_to_transport());assert!(read.commit(&f.temp.database,&r).unwrap().complete_roster);let used:i64=f.temp.database.with_conn(|c|c.query_row("SELECT SUM(length(relation)) FROM app_voice_relation_roster_members",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert!(used<16*1024*1024);assert_eq!(view(&f)[0].observed_time.as_deref(),Some("2"));
}
fn fill_roster(f:&mut Fixture,group:Option<&[u8]>){let mut since=0;snapshot(f,group,since,&[]);for batch in 0..8{let labels=(0..128).map(|i|format!("member-{batch}-{i}").into_bytes()).collect::<Vec<_>>();let items=labels.iter().map(|l|(l.as_slice(),1)).collect::<Vec<_>>();let q=query(group,since);let read=prepare(f,q.clone());since+=1;let r=reply(f,q,&body(true,true,since,&items,&[],&[]));assert!(read.commit(&f.temp.database,&r).unwrap().complete_roster);}}
#[test]fn roster_net_neutral_partial_at_local_and_global_capacity_replaces_without_relaxing_limits(){
 let mut f=fixture();for group in [None,Some(b"1-2".as_slice()),Some(b"2-3".as_slice()),Some(b"3-4".as_slice())]{fill_roster(&mut f,group);}assert_eq!(view(&f).iter().map(|r|r.members).sum::<usize>(),4096);
 let q=query(None,8);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,true,9,&[(b"new-member",1)],&[],&[b"member-0-0"]));let v=read.commit(&f.temp.database,&r).unwrap();assert!(v.complete_roster);assert_eq!(v.members,1024);assert_eq!(view(&f).iter().map(|r|r.members).sum::<usize>(),4096);
 let q=query(None,9);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,true,10,&[(b"one-too-many",1)],&[],&[]));assert_eq!(read.commit(&f.temp.database,&r).err(),Some("app_account_relation_roster_capacity"));let rows=view(&f);let row=rows.iter().find(|r|r.target_kind=="buddy").unwrap();assert_eq!(row.members,1024);assert_eq!(row.observed_time.as_deref(),Some("9"));assert!(row.historical_complete);
}
#[test]fn roster_net_neutral_type20_event_at_capacity_ignores_add_before_remove_wire_order(){
 let mut f=fixture();fill_roster(&mut f,None);observe(&f,None,Some(8),Some(9),&[(b"new-member",1),(b"member-0-0",20)]);let rows=view(&f);assert_eq!(rows[0].members,1024);assert_eq!(rows[0].observed_time.as_deref(),Some("9"));assert!(rows[0].historical_complete);
}
#[test]fn roster_capacity_replacement_deletes_roll_back_if_public_event_commit_fails(){
 let mut f=fixture();fill_roster(&mut f,None);f.temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER fail_roster_delta BEFORE INSERT ON app_events WHEN NEW.event_type='app_voice.relation_roster_observed' BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();let q=query(None,8);let read=prepare(&f,q.clone());let r=reply(&mut f,q,&body(true,true,9,&[(b"new-member",1)],&[],&[b"member-0-0"]));assert_eq!(read.commit(&f.temp.database,&r).err(),Some("app_account_relation_roster_storage_failed"));assert_eq!(view(&f)[0].members,1024);assert_eq!(view(&f)[0].observed_time.as_deref(),Some("8"));
 let retained:bool=f.temp.database.with_conn(|c|c.query_row("SELECT EXISTS(SELECT 1 FROM app_voice_relation_roster_members WHERE instr(relation,?1)>0)",[b"member-0-0".as_slice()],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert!(retained);
}
